from copy import deepcopy
from datetime import datetime
from typing import Any

from lfx.base.tools.run_flow import RunFlowBaseComponent
from lfx.log.logger import logger
from lfx.schema.data import Data
from lfx.schema.dotdict import dotdict


class RunFlowComponent(RunFlowBaseComponent):
    display_name = "Run Flow"
    description = (
        "Executes another flow from within the same project. Can also be used as a tool for agents."
        " \n **Select a Flow to use the tool mode**"
    )
    documentation: str = "https://docs.langflow.org/run-flow"
    beta = True
    name = "RunFlow"
    icon = "Workflow"

    # Keep the concrete class templates detached from the base-class templates;
    # Component.__init__ still makes the per-instance copies used at runtime.
    inputs = deepcopy(RunFlowBaseComponent.get_base_inputs())
    outputs = deepcopy(RunFlowBaseComponent.get_base_outputs())

    async def update_build_config(
        self,
        build_config: dotdict,
        field_value: Any,
        field_name: str | None = None,
    ):
        missing_keys = [key for key in self.default_keys if key not in build_config]
        for key in missing_keys:  # TODO: create a defaults dict to avoid hardcoding the defaults here
            if key == "flow_name_selected":
                build_config[key] = {"options": [], "options_metadata": [], "value": None}
            elif key == "flow_id_selected":
                build_config[key] = {"value": None}
            elif key == "cache_flow":
                build_config[key] = {"value": False}
            else:
                build_config[key] = {}
        if field_name == "flow_name_selected" and (build_config.get("is_refresh", False) or field_value is None):
            # refresh button was clicked or componented was initialized, so list the flows
            options: list[str] = await self.alist_flows_by_flow_folder()
            build_config["flow_name_selected"]["options"] = [flow.data["name"] for flow in options]
            build_config["flow_name_selected"]["options_metadata"] = []
            for flow in options:
                # populate options_metadata
                build_config["flow_name_selected"]["options_metadata"].append(
                    {"id": flow.data["id"], "updated_at": flow.data["updated_at"]}
                )
                # update selected flow if it is stale
                if str(flow.data["id"]) == self.flow_id_selected:
                    await self.check_and_update_stale_flow(flow, build_config)
        elif field_name in {"flow_name_selected", "flow_id_selected"} and field_value is not None:
            # flow was selected by name or id, so get the flow and update the bcfg
            try:
                # derive flow id if the field_name is flow_name_selected
                build_config["flow_id_selected"]["value"] = (
                    self.get_selected_flow_meta(build_config, "id") or build_config["flow_id_selected"]["value"]
                )
                updated_at = self.get_selected_flow_meta(build_config, "updated_at")
                await self.load_graph_and_update_cfg(
                    build_config, build_config["flow_id_selected"]["value"], updated_at
                )
            except Exception as e:
                msg = f"Error building graph for flow {field_value}"
                await logger.aexception(msg)
                raise RuntimeError(msg) from e

        return build_config

    def get_selected_flow_meta(self, build_config: dotdict, field: str) -> dict:
        """Get the selected flow's metadata from the build config."""
        return build_config.get("flow_name_selected", {}).get("selected_metadata", {}).get(field)

    async def load_graph_and_update_cfg(
        self,
        build_config: dotdict,
        flow_id: str,
        updated_at: str | datetime,
    ) -> None:
        """Load a flow's graph and update the build config."""
        graph = await self.get_graph(
            flow_id_selected=flow_id,
            updated_at=self.get_str_isots(updated_at),
        )
        self.update_build_config_from_graph(build_config, graph)

    def should_update_stale_flow(self, flow: Data, build_config: dotdict) -> bool:
        """Check if the flow should be updated."""
        return (
            (updated_at := self.get_str_isots(flow.data["updated_at"]))  # true updated_at date just fetched from db
            and (stale_at := self.get_selected_flow_meta(build_config, "updated_at"))  # outdated date in bcfg
            and self._parse_timestamp(updated_at) > self._parse_timestamp(stale_at)  # stale flow condition
        )

    async def check_and_update_stale_flow(self, flow: Data, build_config: dotdict) -> None:
        """Check if the flow should be updated and update it if necessary."""
        # TODO: improve contract/return value
        if self.should_update_stale_flow(flow, build_config):
            await self.load_graph_and_update_cfg(
                build_config,
                flow.data["id"],
                flow.data["updated_at"],
            )

    def get_str_isots(self, date: datetime | str) -> str:
        """Get a string timestamp from a datetime or string."""
        return date.isoformat() if hasattr(date, "isoformat") else date

import json
import re
import uuid
import httpx

from langflow.custom import Component
from langflow.io import MessageTextInput, StrInput, SecretStrInput, Output
from langflow.schema.message import Message


class MiraDynamicDispatcher(Component):
    display_name = "Mira Dynamic Dispatcher"
    description = (
        "Dispatches validated Router decisions to specialists "
        "with controlled project-context resolution."
    )

    inputs = [
        MessageTextInput(
            name="router_response",
            display_name="Router Response",
            required=True,
        ),
        MessageTextInput(
            name="user_request",
            display_name="Original User Request",
            required=True,
        ),
        StrInput(
            name="base_url",
            display_name="Langflow Server URL",
            value="http://localhost:7860",
        ),
        SecretStrInput(
            name="api_key",
            display_name="Langflow API Key",
            required=True,
        ),
        StrInput(
            name="active_project",
            display_name="Active Project Context",
            value="",
            info=(
                "Set to ABCDE Ltd. AI Adoption Project only "
                "when this flow is dedicated to that project."
            ),
        ),
        StrInput(name="planner_id", display_name="Planner Flow ID"),
        StrInput(name="risk_id", display_name="Risk Flow ID"),
        StrInput(name="status_id", display_name="Status Flow ID"),
        StrInput(name="milestone_id", display_name="Milestone Flow ID"),
    ]

    outputs = [
        Output(
            name="response",
            display_name="Final Response",
            method="dispatch",
        )
    ]

    @staticmethod
    def resolve_project_context(request, agent, active_project):
        """
        Resolve implicit project references only when a
        trusted active project is explicitly configured.

        Never replace the original request used by the Router.
        """
        if agent != "risk_assessor":
            return request, None

        active = str(active_project or "").strip()
        if not active:
            return request, None

        accepted_names = {
            "abcde ltd. ai adoption project",
            "ai adoption project at abcde ltd.",
        }

        if active.lower() not in accepted_names:
            return request, None

        lower = request.lower()

        # An explicitly named different organization must
        # never be silently interpreted as ABCDE.
        if re.search(r"\babcde\b", lower):
            return request, None

        # Only resolve the specific contextual expressions
        # covered by this project's test cases.
        implicit_patterns = [
            r"\bthis ai adoption project\b",
            r"\bthe current ai adoption project\b",
            r"\bour ai adoption project\b",
            r"\bthis project\b",
            r"\bthe current project\b",
        ]

        if not any(re.search(p, lower) for p in implicit_patterns):
            return request, None

        # Do not rewrite requests that also identify another
        # organization or project explicitly.
        other_project = re.search(
            r"\b(?:for|at|of)\s+"
            r"([A-Z][A-Za-z0-9&.-]*(?:\s+[A-Z][A-Za-z0-9&.-]*)*)"
            r"\s+(?:Ltd\.?|Inc\.?|LLC|Corp\.?)",
            request,
        )
        if other_project:
            return request, (
                "Please confirm which project you want "
                "to assess before I use ABCDE Ltd. data."
            )

        # Preserve the user question and attach the trusted
        # project identity as separate execution context.
        grounded_request = (
            f"{request}\n\n"
            "Active project context (configured by the "
            "Mira orchestrator): "
            "AI Adoption Project at ABCDE Ltd.\n"
            "Use only the available ABCDE project sources. "
            "Do not invent missing source facts."
        )

        return grounded_request, None

    async def dispatch(self) -> Message:
        try:
            raw = self.router_response
            if hasattr(raw, "text"):
                raw = raw.text

            result = json.loads(str(raw))

            if result.get("validation_status") != "PASS":
                return Message(text="Router validation failed.")

            data = result.get("validated_data", {})
            status = data.get("routing_status")

            if status == "CLARIFICATION_REQUIRED":
                return Message(
                    text=data.get("clarification_question")
                    or "Please clarify your request."
                )

            if status == "UNSUPPORTED":
                return Message(
                    text="This request is outside Mira's supported capabilities."
                )

            if status != "ROUTED":
                return Message(
                    text="Unable to determine the routing decision."
                )

            registry = {
                "planner": self.planner_id,
                "risk_assessor": self.risk_id,
                "status_reporter": self.status_id,
                "milestone_tracker": self.milestone_id,
            }

            agent = data.get("selected_agent")
            flow_id = registry.get(agent)

            if not flow_id:
                return Message(
                    text=f"No configured specialist for: {agent}"
                )

            request = self.user_request
            if hasattr(request, "text"):
                request = request.text
            request = str(request).strip()

            # Check the original request before adding context.
            if not request or request != data.get("user_request"):
                return Message(
                    text="Original request does not match the Router decision."
                )

            specialist_request, clarification = (
                self.resolve_project_context(
                    request,
                    agent,
                    self.active_project,
                )
            )

            if clarification:
                return Message(text=clarification)

            url = (
                f"{str(self.base_url).rstrip('/')}"
                f"/api/v1/run/{flow_id}"
            )

            key = self.api_key
            if hasattr(key, "get_secret_value"):
                key = key.get_secret_value()

            async with httpx.AsyncClient(
                timeout=120,
                trust_env=False,
            ) as client:
                response = await client.post(
                    url,
                    headers={"x-api-key": str(key)},
                    json={
                        "input_value": specialist_request,
                        "input_type": "chat",
                        "output_type": "chat",
                        "session_id": str(uuid.uuid4()),
                    },
                )

                response.raise_for_status()
                payload = response.json()

            outputs = payload.get("outputs", [])

            for group in outputs:
                for item in group.get("outputs", []):
                    message = item.get(
                        "results", {}
                    ).get("message")

                    if isinstance(message, dict):
                        text = (
                            message.get("text")
                            or message.get("data", {}).get("text")
                        )
                        if text is not None:
                            return Message(text=str(text))

                    if isinstance(message, str):
                        return Message(text=message)

                    messages = item.get("messages", [])
                    if messages:
                        first = messages[0]
                        text = (
                            first.get("message")
                            or first.get("text")
                        )
                        if text is not None:
                            return Message(text=str(text))

            return Message(
                text=json.dumps(
                    payload,
                    ensure_ascii=False,
                )
            )

        except Exception as exc:
            self.status = str(exc)
            return Message(
                text=f"Dispatcher execution failed: {exc}"
            )
